    "credit" numeric(3,1) NOT NULL,
    "hours" integer NOT NULL,
    "course_type" character varying(10) NOT NULL,
    "teacher_no" character varying(20) NOT NULL,
    "semester" character varying(20) NOT NULL,
    CONSTRAINT dm_course_pkey PRIMARY KEY ("id")
);

